/// Conformance tests: replay every case from fixtures/cases.json (generated by gen.mjs from the
/// TypeScript reference implementation) and assert the Rust output matches.
use review_anchor::{
    edits_between, offset_at, position_at, similarity, track, AnchorStatus, Edit,
    TrackedRange, TrackedRangeCandidate,
};
use serde_json::Value;

fn load_cases() -> Vec<Value> {
    let data = include_str!("fixtures/cases.json");
    serde_json::from_str(data).expect("fixtures/cases.json should be valid JSON")
}

fn parse_anchor(v: &Value) -> TrackedRange {
    let status = match v["status"].as_str().expect("status") {
        "active" => AnchorStatus::Active,
        "modified" => AnchorStatus::Modified,
        "removed" => AnchorStatus::Removed,
        "ambiguous" => AnchorStatus::Ambiguous,
        s => panic!("unknown status: {s}"),
    };
    let candidates = v.get("candidates").and_then(|c| {
        if c.is_null() {
            return None;
        }
        c.as_array().map(|arr| {
            arr.iter()
                .map(|cv| TrackedRangeCandidate {
                    from: cv["from"].as_u64().expect("candidate from"),
                    to: cv["to"].as_u64().expect("candidate to"),
                })
                .collect()
        })
    });
    TrackedRange {
        version: v["version"].as_str().expect("version").to_string(),
        from: v["from"].as_u64().expect("from"),
        to: v["to"].as_u64().expect("to"),
        text: v["text"].as_str().expect("text").to_string(),
        prefix: v["prefix"].as_str().expect("prefix").to_string(),
        suffix: v["suffix"].as_str().expect("suffix").to_string(),
        status,
        original: v["original"].as_str().expect("original").to_string(),
        candidates,
        extra: serde_json::Map::new(),
    }
}

fn parse_edits(v: &Value) -> Vec<Edit> {
    match v.as_array() {
        Some(arr) => arr
            .iter()
            .map(|e| Edit {
                from: e["from"].as_u64().expect("edit from") as usize,
                to: e["to"].as_u64().expect("edit to") as usize,
                insert: e["insert"].as_str().expect("edit insert").to_string(),
            })
            .collect(),
        None => vec![],
    }
}

fn status_str(s: &AnchorStatus) -> &'static str {
    match s {
        AnchorStatus::Active => "active",
        AnchorStatus::Modified => "modified",
        AnchorStatus::Removed => "removed",
        AnchorStatus::Ambiguous => "ambiguous",
    }
}

#[test]
fn replay_all_cases() {
    let cases = load_cases();
    let mut passed = 0;
    let mut failed = 0;
    let mut failures: Vec<String> = Vec::new();

    for case in &cases {
        let id = case["id"].as_u64().unwrap_or(0);
        let name = case["name"].as_str().unwrap_or("unknown");
        let input = &case["input"];
        let expected = &case["expected"];

        let input_type = input.get("type").and_then(|v| v.as_str()).unwrap_or("track");

        match input_type {
            "track" => {
                let anchor = parse_anchor(&input["anchor"]);
                let before = input["before"].as_str();
                let after = input["after"].as_str().expect("after");
                let version = input["version"].as_str().expect("version");
                let edits = input.get("edits").and_then(|e| {
                    if e.is_null() {
                        None
                    } else {
                        Some(parse_edits(e))
                    }
                });

                let result = track(
                    &anchor,
                    before,
                    after,
                    version,
                    edits.as_deref(),
                );

                let exp = parse_anchor(expected);
                let ok = result.status == exp.status
                    && result.from == exp.from
                    && result.to == exp.to;

                if ok {
                    passed += 1;
                } else {
                    failed += 1;
                    failures.push(format!(
                        "#{id} {name}: expected status={} from={} to={}, got status={} from={} to={}",
                        status_str(&exp.status),
                        exp.from,
                        exp.to,
                        status_str(&result.status),
                        result.from,
                        result.to,
                    ));
                }
            }
            "similarity" => {
                let a = input["a"].as_str().expect("a");
                let b = input["b"].as_str().expect("b");
                let exp = expected["similarity"].as_f64().expect("similarity");
                let result = similarity(a, b);
                if (result - exp).abs() < 1e-10 {
                    passed += 1;
                } else {
                    failed += 1;
                    failures.push(format!(
                        "#{id} {name}: expected similarity={exp}, got {result}"
                    ));
                }
            }
            "offset" => {
                let text = input["text"].as_str().expect("text");
                let line = input["line"].as_u64().expect("line") as usize;
                let character = input["character"].as_u64().expect("character") as usize;
                let exp_offset = expected["offset"].as_u64().expect("offset") as usize;
                let result_offset = offset_at(text, line, character);

                let exp_pos = &expected["position"];
                let exp_line = exp_pos["line"].as_u64().expect("pos line") as usize;
                let exp_char = exp_pos["character"].as_u64().expect("pos char") as usize;
                let (result_line, result_char) = position_at(text, result_offset);

                if result_offset == exp_offset && result_line == exp_line && result_char == exp_char
                {
                    passed += 1;
                } else {
                    failed += 1;
                    failures.push(format!(
                        "#{id} {name}: expected offset={exp_offset} pos=({exp_line},{exp_char}), got offset={result_offset} pos=({result_line},{result_char})"
                    ));
                }
            }
            "edits" => {
                let before = input["before"].as_str().expect("before");
                let after = input["after"].as_str().expect("after");
                let result = edits_between(before, after);
                // Verify the edits reconstruct the `after` text when applied to `before`
                let mut reconstructed: Vec<u16> = before.encode_utf16().collect();
                let mut shift: isize = 0;
                for edit in &result {
                    let from = (edit.from as isize + shift) as usize;
                    let to = (edit.to as isize + shift) as usize;
                    let insert: Vec<u16> = edit.insert.encode_utf16().collect();
                    let insert_len = insert.len();
                    reconstructed.splice(from..to, insert);
                    shift += insert_len as isize - (edit.to as isize - edit.from as isize);
                }
                let reconstructed_str = String::from_utf16_lossy(&reconstructed);
                if reconstructed_str == after {
                    passed += 1;
                } else {
                    failed += 1;
                    failures.push(format!(
                        "#{id} {name}: edits don't reconstruct the after text"
                    ));
                }
            }
            other => {
                failures.push(format!("#{id} {name}: unknown case type '{other}'"));
                failed += 1;
            }
        }
    }

    // Print summary
    let total = passed + failed;
    eprintln!("\n--- Conformance Results ---");
    eprintln!("Passed: {passed}/{total}");
    if !failures.is_empty() {
        eprintln!("\nFailures ({failed}):");
        for (i, f) in failures.iter().enumerate() {
            eprintln!("  {}: {f}", i + 1);
            if i >= 49 {
                eprintln!("  ... and {} more", failures.len() - 50);
                break;
            }
        }
    }
    assert!(
        failed == 0,
        "{failed} of {total} cases failed (see above for details)"
    );
}
